const subjects=[
 {id:'roman',name:'Román',glyph:'Á',color:'#d9eadc',desc:'magyar anyanyelvűeknek',lessons:[['Bemutatkozás románul','A bemutatkozás a legegyszerűbb párbeszédek alapja. Használd a „Mă numesc…” (A nevem…) és „Sunt elev/elevă” (diák vagyok) szerkezeteket. A románban a főnevek neme fontos: az elev fiú, az elevă lány.','Mă numesc = a nevem\nSunt = vagyok\nelev / elevă = fiú diák / lány diák'],['Család és mindennapok','A családtagok megnevezései: mama, tata, frate, soră. Figyeld meg, hogy a birtokos szerkezetekben gyakori az „meu/mea” alak: fratele meu – a fiútestvérem.','mama = anya\ntata = apa\nfrate = fiútestvér\nsoră = lánytestvér'],['Idő és dátumok','A hét napjai és az időpontok pontos használata segíti a mindennapi kommunikációt. Kérdésnél: „Cât e ceasul?” – Mennyi az idő?','azi = ma\nmâine = holnap\nieri = tegnap\nora = óra']]},
 {id:'magyar',name:'Magyar',glyph:'M',color:'#f0d8c2',desc:'nyelv és irodalom',lessons:[['A kommunikáció tényezői','A kommunikáció feladó és címzett között zajló üzenetátadás. A közös kód és a csatorna teszi lehetővé a megértést. A szövegkörnyezet befolyásolja az üzenet jelentését.','feladó = az üzenet létrehozója\ncímzett = az üzenet befogadója\nkód = közös jelrendszer\ncsatorna = közvetítő közeg'],['A reformkor irodalma','A reformkor a magyar nyelv és nemzeti kultúra megújulásának korszaka. Kölcsey, Vörösmarty és Petőfi művei a nemzeti öntudat fontos hangjai.','reformkor = 1825–1848\nKölcsey Ferenc = Himnusz\nVörösmarty Mihály = Szózat\nPetőfi Sándor = forradalmi költő'],['Nyelvtani alapok','A mondat szerkezete szerint lehet egyszerű vagy összetett. Az alany és állítmány a mondat fő részei, a bővítmények pontosítják őket.','alany = kiről/miről állítunk\nállítmány = mit állítunk\nbővítmény = pontosító mondatrész']]},
 {id:'tori',name:'Történelem',glyph:'T',color:'#d7e5ee',desc:'események és összefüggések',lessons:[['Az ókori Hellász','A görög poliszok önálló városállamok voltak. Athénban kialakult a közvetlen demokrácia, ahol a polgárok közvetlenül hoztak döntéseket.','polisz = városállam\ndemokrácia = népuralom\nAkropolisz = fellegvár\nKr. e. 5. század = Athén fénykora'],['A honfoglalás','A magyarság a 9. század végén foglalta el a Kárpát-medencét. A törzsszövetséget Árpád vezette, a letelepedés új államszervezeti korszakot indított.','895/896 = honfoglalás\nÁrpád = fejedelem\nKárpát-medence = új szállásterület'],['Az 1848–49-es forradalom','Március 15-én Pesten kitört a forradalom. A 12 pont és a Nemzeti dal a polgári átalakulás követeléseit fogalmazta meg.','1848. március 15. = forradalom\n12 pont = követelések\nKossuth Lajos = politikus\nBatthyány Lajos = első miniszterelnök']]},
 {id:'foldrajz',name:'Földrajz',glyph:'F',color:'#ddd9ed',desc:'földünk és térségeink',lessons:[['A Föld belső szerkezete','A Föld három fő része a kéreg, a köpeny és a mag. A kőzetlemezek mozgása földrengéseket és vulkáni tevékenységet okozhat.','földkéreg = külső szilárd réteg\nköpeny = kéreg alatti réteg\nmag = belső, forró rész\nkőzetlemez = mozgó kéregdarab'],['Éghajlati övezetek','Az éghajlatot a földrajzi szélesség, a domborzat és a tengertől való távolság alakítja. Három fő övezetet különítünk el: forró, mérsékelt és hideg.','éghajlat = hosszú távú időjárás\nforró övezet = térítők között\nmérsékelt övezet = évszakok váltakoznak'],['Magyarország tájai','Hazánk medencejellegű ország. Nagytájai között találjuk az Alföldet, a Kisalföldet, az Alpokalját, a Dunántúli-dombságot és az Északi-középhegységet.','Alföld = legnagyobb nagytáj\nKékes = legmagasabb pont\nDuna = fő folyó\nmedencejelleg = hegyek övezik']]}
];
